# DK HCF.  Haderslev - Christiansfeld
#
let hc = path("d3.dk.hcf");

with detail = 3, railway = :first :g1000 :pax :removed {
    # point.dk.Haderslev-Amtsb  dk.VHL

    with link = "line.dk.HCF" {
        track(hc[:had + 0.49sw, :had.ys]);
        track(hc[:had.ys - 0.1dl, :ves - 0.49sw]);
    }

    with link = "point.dk.Vesterris", railway = :station {
        track(hc[:ves - 0.5sw, :ves + 0.5sw]);
        marker(:right :de.hp, hc[:ves] >> 0.5lt);
        slabel(:right, hc[:ves] >> 0.5lt >> 1sh + (1.8dt, 1dt),
            "Vesterris"
        );
    }

    with link = "line.dk.HCF" {
        track(hc[:ves + 0.49sw, :nas - 0.49sw]);
    }

    with link = "point.dk.Neder-Åstrup", railway = :station {
        track(hc[:nas - 0.5sw, :nas + 0.5sw]);
        marker(:left :de.bf, hc[:nas] << 0.5lt);
        slabel(:nw, hc[:nas] >> 0.5lt + (0.8dt, -0.5dt),
            "Neder Åstrup"
        );
    }

    with link = "line.dk.HCF" {
        track(hc[:nas + 0.49sw, :nas + 0.81km]);
        #line_label(:right:nw, hc[:nas + 0.8km] >> 0.5lt, "HCF");
        track(hc[:nas + 0.79km, :oas - 0.49sw]);
    }

    with link = "point.dk.Over-Åstrup", railway = :station {
        track(hc[:oas - 0.5sw, :oas + 0.5sw]);
        marker(:left :de.bf, hc[:oas] << 0.5lt);
        slabel(:left, hc[:oas] << 0.5lt << 1sh + (-1.3dt, 0.5dt),
            "Over Åstrup"
        );
    }

    with link = "line.dk.HCF" {
        track(hc[:oas + 0.49sw, :von - 0.49sw]);
    }

    with link = "point.dk.Vonsbæk", railway = :station {
        track(hc[:von - 0.5sw, :von + 0.5sw]);
        marker(:right :de.bf, hc[:von] >> 0.5lt);
        slabel(:right, hc[:von] >> 0.5lt >> 1sh + (1.3dt, 1.1dt),
            "Vonsbæk"
        );
    }

    with link = "line.dk.HCF" {
        track(hc[:von + 0.49sw, :vil - 0.49sw]);
    }

    with link = "point.dk.Vildfang", railway = :station {
        track(hc[:vil - 0.5sw, :vil + 0.5sw]);
        marker(:right :de.hp, hc[:vil] >> 0.9lt);
        slabel(:right, hc[:vil] >> 0.5lt >> 1sh + (1.3dt, 0.9dt),
            "Vildfang"
        );
    }

    with link = "line.dk.HCF" {
        track(hc[:vil + 0.49sw, :sig - 0.49sw]);
    }

    with link = "point.dk.Sillerupgård", railway = :station {
        track(hc[:sig - 0.5sw, :sig + 0.5sw]);
        marker(:left :de.hp, hc[:sig] << 0.5lt);
        slabel(:left, hc[:sig] << 0.5lt << 1sh + (-1.3dt, 1dt),
            "Sillerupgård"
        );
    }

    with link = "line.dk.HCF" {
        track(hc[:sig + 0.49sw, :sil - 0.49sw]);
    }

    with link = "point.dk.Sillerup", railway = :station {
        track(hc[:sil - 0.5sw, :sil + 0.5sw]);
        marker(:right :de.bf, hc[:sil] >> 0.9lt);
        slabel(:right, hc[:sil] >> 0.5lt >> 1sh + (1.5dt, 1.2dt),
            "Sillerup"
        );
    }

    with link = "line.dk.HCF" {
        track(hc[:sil + 0.49sw, :sil + 1.01km]);
        line_label(:right:w, hc[:sil + 1km] >> 0.5lt, "HCF");
        track(hc[:sil + 0.99km, :fje - 0.49sw]);
    }

    with link = "point.dk.Fjelstrup", railway = :station {
        track(hc[:fje - 0.5sw, :fje + 0.5sw]);
        marker(:right :de.bf, hc[:fje] >> 0.9lt);
        slabel(:right, hc[:fje] >> 0.5lt >> 1sh + (1.5dt, 0.9dt),
            "Fjelstrup"
        );
    }

    with link = "line.dk.HCF" {
        track(hc[:fje + 0.49sw, :gam - 0.49sw]);
    }

    with link = "point.dk.Gammelby", railway = :station {
        track(hc[:gam - 0.5sw, :gam + 0.5sw]);
        marker(:left :de.hp, hc[:gam] << 0.5lt);
        slabel(:left, hc[:gam] << 0.5lt << 1sh + (-1.9dt, 1.6dt),
            "Gammelby"
        );
    }

    with link = "line.dk.HCF" {
        track(hc[:gam + 0.49sw, :kel - 0.49sw]);
    }

    with link = "point.dk.Kellergård", railway = :station {
        track(hc[:kel - 0.5sw, :kel + 0.5sw]);
        marker(:right :de.hp, hc[:kel] >> 0.9lt);
        slabel(:right, hc[:kel] >> 0.5lt >> 1sh + (1.7dt, 0dt),
            "Kellergård"
        );
    }

    with link = "line.dk.HCF" {
        track(hc[:kel + 0.49sw, :fav - 0.49sw]);
    }

    with link = "point.dk.Favstrup", railway = :station {
        track(hc[:fav - 0.5sw, :fav + 0.5sw]);
        marker(:right :de.bf, hc[:fav] >> 0.9lt);
        slabel(:right, hc[:fav] >> 0.5lt >> 1sh + (-2.5dt, -1.3dt),
            "Favstrup"
        );
    }

    with link = "line.dk.HCF" {
        track(hc[:fav + 0.49sw, :fav + 1.71km]);
        line_label(:left:ne, hc[:fav + 1.7km] << 0.5lt, "HCF");
        track(hc[:fav + 1.69km, :chr - 0.49sw]);
    }

    with link = "point.dk.Christiansfeld", railway = :station {
        track(hc[:chr - 0.5sw, :chr + 0.5sw]);
        marker(:right :de.bf, hc[:chr] >> 0.9lt);
        slabel(:top, hc[:chr] >> 0.5lt >> 1sh >> 0.4dt,
            span(:bold, "Christiansfeld")
        );
    }
}

